c065.try_sql:
-- A new sequence: CURRVAL before the first NEXTVAL in this session raises ORA-08002
CREATE SEQUENCE lab_c065_seq;
SELECT lab_c065_seq.CURRVAL FROM dual;
-- After NEXTVAL, CURRVAL works
SELECT lab_c065_seq.NEXTVAL AS nextval FROM dual;
SELECT lab_c065_seq.CURRVAL AS currval FROM dual;

c066.try_sql:
-- The number taken before ROLLBACK is lost: only the second row remains, with a gap in the numbering
CREATE SEQUENCE lab_c066_seq;
CREATE TABLE lab_c066_t (id NUMBER, opis VARCHAR2(20));
INSERT INTO lab_c066_t VALUES (lab_c066_seq.NEXTVAL, 'wycofany');
ROLLBACK;
INSERT INTO lab_c066_t VALUES (lab_c066_seq.NEXTVAL, 'zapisany');
SELECT id, opis FROM lab_c066_t;

c068.try_sql:
-- An index created as INVISIBLE, then switched to VISIBLE
CREATE TABLE lab_c068_emp AS SELECT employee_id, last_name FROM employees;
CREATE INDEX lab_c068_ix ON lab_c068_emp (last_name) INVISIBLE;
SELECT index_name, visibility, status FROM user_indexes WHERE index_name = 'LAB_C068_IX';
ALTER INDEX lab_c068_ix VISIBLE;
SELECT index_name, visibility, status FROM user_indexes WHERE index_name = 'LAB_C068_IX';

c069.try_sql:
-- ON COMMIT DELETE ROWS: the row lives until the end of the transaction
CREATE GLOBAL TEMPORARY TABLE lab_c069_gtt (id NUMBER) ON COMMIT DELETE ROWS;
INSERT INTO lab_c069_gtt VALUES (1);
SELECT COUNT(*) AS przed_commit FROM lab_c069_gtt;
-- COMMENT is DDL, so it commits, and the temporary table's rows disappear
COMMENT ON TABLE lab_c069_gtt IS 'tabela tymczasowa';
SELECT COUNT(*) AS po_commit FROM lab_c069_gtt;

c600.try_sql:
-- A private synonym: it lives in your schema and points to EMPLOYEES
CREATE SYNONYM lab_c600_emp FOR employees;
SELECT COUNT(*) AS pracownicy FROM lab_c600_emp;
SELECT synonym_name, table_owner, table_name FROM user_synonyms WHERE synonym_name = 'LAB_C600_EMP';
-- Public synonyms (for example DUAL) are owned by PUBLIC
SELECT owner, synonym_name, table_owner, table_name FROM all_synonyms WHERE synonym_name = 'DUAL';

