CREATE TABLE lab_c604_emp AS SELECT employee_id, last_name, salary FROM employees;
CREATE VIEW lab_c604_v AS SELECT employee_id, last_name FROM lab_c604_emp;
CREATE OR REPLACE VIEW lab_c604_v AS SELECT employee_id, last_name, salary FROM lab_c604_emp;
