c1600.try_sql:
-- A public synonym is owned by PUBLIC; USER_SYNONYMS shows only private ones
SELECT owner, synonym_name, table_owner, table_name FROM all_synonyms WHERE synonym_name = 'DUAL';
SELECT synonym_name FROM user_synonyms;

c1601.try_sql:
-- OR REPLACE moves the synonym from EMPLOYEES to DEPARTMENTS
CREATE SYNONYM lab_c1601_s FOR employees;
CREATE OR REPLACE SYNONYM lab_c1601_s FOR departments;
SELECT synonym_name, table_name FROM user_synonyms WHERE synonym_name = 'LAB_C1601_S';
-- A plain CREATE on a name already in use: ORA-00955
CREATE SYNONYM lab_c1601_s FOR employees;

c1603.try_sql:
-- Drop the table behind the synonym: using the synonym raises ORA-00980
CREATE TABLE lab_c1603_t AS SELECT * FROM departments;
CREATE SYNONYM lab_c1603_s FOR lab_c1603_t;
DROP TABLE lab_c1603_t PURGE;
SELECT COUNT(*) FROM lab_c1603_s;
-- The table exists again: the same synonym works without being created again
CREATE TABLE lab_c1603_t AS SELECT * FROM departments;
SELECT COUNT(*) AS dzialy FROM lab_c1603_s;

c1604.try_sql:
-- INSERT and UPDATE through the synonym change the base table
CREATE TABLE lab_c1604_t AS SELECT department_id, department_name FROM departments;
CREATE SYNONYM lab_c1604_s FOR lab_c1604_t;
INSERT INTO lab_c1604_s VALUES (999, 'Lab');
UPDATE lab_c1604_s SET department_name = 'Lab przez synonim' WHERE department_id = 999;
SELECT department_id, department_name FROM lab_c1604_t WHERE department_id = 999;

c1605.try_sql:
-- BY DEFAULT ON NULL: an explicit NULL gets a sequence number, your own value goes through too
CREATE TABLE lab_c1605_on_null (id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY, opis VARCHAR2(20));
INSERT INTO lab_c1605_on_null VALUES (NULL, 'NULL -> numer');
INSERT INTO lab_c1605_on_null VALUES (100, 'własna wartość');
SELECT id, opis FROM lab_c1605_on_null ORDER BY id;
-- ALWAYS: you may not supply your own value
CREATE TABLE lab_c1605_always (id NUMBER GENERATED ALWAYS AS IDENTITY, opis VARCHAR2(20));
INSERT INTO lab_c1605_always VALUES (100, 'własna wartość');

c1606.try_sql:
-- IDENTITY gets a system sequence ISEQ$$_... and NOT NULL at once
CREATE TABLE lab_c1606_t (id NUMBER GENERATED ALWAYS AS IDENTITY, opis VARCHAR2(20));
SELECT column_name, generation_type, sequence_name FROM user_tab_identity_cols WHERE table_name = 'LAB_C1606_T';
SELECT column_name, nullable FROM user_tab_columns WHERE table_name = 'LAB_C1606_T' ORDER BY column_id;
-- A second IDENTITY column in the same table: ORA-30669
ALTER TABLE lab_c1606_t ADD (id2 NUMBER GENERATED ALWAYS AS IDENTITY);

c1607.try_sql:
