CREATE SEQUENCE lab_c1607_seq;
CREATE TABLE lab_c1607_t (id NUMBER DEFAULT lab_c1607_seq.NEXTVAL, opis VARCHAR2(20));
DROP SEQUENCE lab_c1607_seq;
SELECT column_name, data_default FROM user_tab_columns WHERE table_name = 'LAB_C1607_T' AND column_name = 'ID';
