c1610.try_sql:
-- KEEP INDEX: the primary key disappears, its index stays
CREATE TABLE lab_c1610_t (id NUMBER CONSTRAINT lab_c1610_pk PRIMARY KEY, opis VARCHAR2(20));
ALTER TABLE lab_c1610_t DROP PRIMARY KEY KEEP INDEX;
SELECT COUNT(*) AS klucze FROM user_constraints WHERE table_name = 'LAB_C1610_T' AND constraint_type = 'P';
SELECT index_name, uniqueness FROM user_indexes WHERE table_name = 'LAB_C1610_T';

c1611.try_sql:
-- Sort first in an inline view, then ROWNUM: the 3 lowest salaries
SELECT *
FROM   (SELECT last_name, salary FROM employees ORDER BY salary)
WHERE  ROWNUM <= 3;
-- ROWNUM in the same query: 3 arbitrary rows, sorted only afterwards
SELECT last_name, salary FROM employees WHERE ROWNUM <= 3 ORDER BY salary;
